style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
body {
        background: url("https://i.imgur.com/yourgif.gif") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ffffff !important;
    }

    /* Transparent containers */
    .container, .content, .main, .page-content, .header, .navbar, .footer {
        background-color: rgba(0, 0, 0, 0.6) !important;
        border-radius: 10px !important;
    }

    /* Buttons */
    button, .btn, .btn-primary {
        background-color: #111111 !important;
        border: 1px solid #ff2e63 !important;
        color: #ff2e63 !important;
        border-radius: 6px !important;
    }

    button:hover, .btn:hover, .btn-primary:hover {
        background-color: #ff2e63 !important;
        color: #ffffff !important;
    }

    /* Links */
    a {
        color: #ff2e63 !important;
    }
    a:hover {
        color: #ff99b5 !important;
        text-decoration: underline !important;
    }

    /* Rounded images */
    img {
        border-radius: 10px !important;
    }
}
